using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;
// Reusable match-only HP/TG/combo display. Training panels and frame history stay in TrainingOverlay.
[DefaultExecutionOrder(1600)]public sealed class MatchHud:MonoBehaviour {
 public sealed class ContactState {public int count;public double totalDamage,lastDamage;public TrainingResolvedContact last;public bool hasContact,active;public float displayLeft;int sequence,reset=-1;float hp;
  public void Observe(TrainingFighter defender,float dt,float hold){if(defender==null)return;if(reset!=defender.InputBuffer.ResetVersion){Clear();reset=defender.InputBuffer.ResetVersion;sequence=defender.ContactSequence;hp=defender.Health;return;}bool changed=sequence!=defender.ContactSequence;if(changed){sequence=defender.ContactSequence;last=defender.LastResolvedContact;hasContact=true;lastDamage=Math.Max(0,hp-defender.Health);if(last.hit){if(!active){count=0;totalDamage=0;}count++;totalDamage+=lastDamage;active=true;displayLeft=hold;}else active=false;}if(!changed&&defender.StunRemaining<=0&&defender.HitstopRemaining<=0)active=false;if(!active)displayLeft=Mathf.Max(0,displayLeft-dt);hp=defender.Health;}
  public void RebaseHP(float value){hp=value;}
  public void Clear(){count=0;totalDamage=lastDamage=0;hasContact=active=false;displayLeft=0;last=default;}
 }
 public TrainingFighter first,second;public MatchDisplayProfile profile;public readonly ContactState FirstAttack=new ContactState(),SecondAttack=new ContactState();
 public Rect Viewport{get;private set;}public readonly Dictionary<string,Rect> Rects=new Dictionary<string,Rect>();readonly Dictionary<string,Image> images=new Dictionary<string,Image>();readonly Dictionary<string,Text> texts=new Dictionary<string,Text>();RectTransform root;Font font;bool built;
 public void Configure(Transform parent,TrainingFighter p,TrainingFighter o,MatchDisplayProfile settings,Font labelFont){first=p;second=o;profile=settings;font=labelFont;if(built)return;FirstAttack.Observe(o,0,profile.completedComboSeconds);SecondAttack.Observe(p,0,profile.completedComboSeconds);built=true;var g=new GameObject("Match HUD (shared)",typeof(RectTransform));g.layer=5;g.transform.SetParent(parent,false);root=(RectTransform)g.transform;root.anchorMin=Vector2.zero;root.anchorMax=Vector2.one;root.offsetMin=root.offsetMax=Vector2.zero;foreach(string id in new[]{"hp1","hp2","hpfill1","hpfill2","name1","name2","tg1","tg2","tgfill1","tgfill2","number1","number2","band1","band2","combo1","combo2"}){var item=new GameObject(id,typeof(RectTransform),typeof(Image));item.layer=5;item.transform.SetParent(root,false);images[id]=item.GetComponent<Image>();images[id].raycastTarget=false;var label=new GameObject("Label",typeof(RectTransform),typeof(Text));label.layer=5;label.transform.SetParent(item.transform,false);var rt=(RectTransform)label.transform;rt.anchorMin=Vector2.zero;rt.anchorMax=Vector2.one;rt.offsetMin=new Vector2(6,0);rt.offsetMax=new Vector2(-6,0);var t=label.GetComponent<Text>();t.font=font;t.color=Color.white;t.alignment=TextAnchor.MiddleLeft;t.raycastTarget=false;t.horizontalOverflow=HorizontalWrapMode.Overflow;t.verticalOverflow=VerticalWrapMode.Truncate;texts[id]=t;}}
 void FixedUpdate(){if(profile==null)return;FirstAttack.Observe(second,Time.fixedDeltaTime,profile.completedComboSeconds);SecondAttack.Observe(first,Time.fixedDeltaTime,profile.completedComboSeconds);}
 void Rebind(){if(images.Count>0||root==null)return;foreach(Transform child in root){var image=child.GetComponent<Image>();var label=child.Find("Label");if(image!=null&&label!=null){images[child.name]=image;texts[child.name]=label.GetComponent<Text>();}}}
 public void Refresh(Rect viewport){Rebind();if(!built||first==null||second==null||profile==null)return;Viewport=viewport;float s=viewport.width/1600;Rects.Clear();foreach(bool one in new[]{true,false}){string n=one?"1":"2";var f=one?first:second;float x=one?26:924;Put("hp"+n,new Rect(x,35,650,24),new Color(.02f,.035f,.05f,.85f),s);float hp=f.definition.maxHealth>0?Mathf.Clamp01(f.Health/f.definition.maxHealth):0;Put("hpfill"+n,new Rect(one?x:x+650*(1-hp),35,650*hp,24),one?new Color(.25f,.86f,.58f):new Color(.27f,.68f,.98f),s);Put("name"+n,new Rect(x,9,650,24),Color.clear,s);texts["name"+n].text=$"{n}P  {f.CharacterName}   HP {f.Health:0.##} / {f.definition.maxHealth:0.##}";texts["name"+n].alignment=one?TextAnchor.MiddleLeft:TextAnchor.MiddleRight;
 float gx=one?130:924;Put("tg"+n,new Rect(gx,850,546,26),new Color(.02f,.035f,.05f,.85f),s);double v=f.Tension.Gauge;float fill=MatchDisplayProfile.TGFill(v);Put("tgfill"+n,new Rect(one?gx:gx+546*(1-fill),850,546*fill,26),profile.TGColor(v),s);Put("number"+n,new Rect(one?26:1476,842,98,42),new Color(.02f,.035f,.05f,.85f),s);texts["number"+n].text="TG "+(double.IsNaN(v)||double.IsInfinity(v)?"invalid":v.ToString("0.##"));texts["number"+n].alignment=TextAnchor.MiddleCenter;Put("band"+n,new Rect(gx,877,546,18),Color.clear,s);texts["band"+n].text=MatchDisplayProfile.TGBand(v)+(Math.Abs(v)>200?"  | outside display scale":"");texts["band"+n].color=profile.TGColor(v);texts["band"+n].alignment=one?TextAnchor.MiddleLeft:TextAnchor.MiddleRight;
 var combo=one?FirstAttack:SecondAttack;Put("combo"+n,new Rect(one?38:1262,350,300,60),Color.clear,s);texts["combo"+n].text=combo.count>0&&(combo.active||combo.displayLeft>0)?combo.count+" HIT":"";texts["combo"+n].alignment=one?TextAnchor.MiddleLeft:TextAnchor.MiddleRight;texts["combo"+n].fontSize=Mathf.Max(16,Mathf.RoundToInt(34*s));}}
 void Put(string id,Rect logical,Color color,float s){var rect=new Rect(Viewport.x+logical.x*s,Viewport.y+logical.y*s,logical.width*s,logical.height*s);Rects[id]=rect;var rt=(RectTransform)images[id].transform;rt.anchorMin=rt.anchorMax=new Vector2(0,1);rt.pivot=new Vector2(0,1);rt.anchoredPosition=new Vector2(rect.x,-rect.y);rt.sizeDelta=rect.size;images[id].color=color;texts[id].fontSize=Mathf.Max(10,Mathf.RoundToInt((id.StartsWith("band")?14:18)*s));}
 public string TextFor(string id)=>texts.ContainsKey(id)?texts[id].text:"";
 void OnDestroy(){if(root!=null)Destroy(root.gameObject);}
}
